/**
 * PORTFOLIO: the single file for all visual work on the site.
 *
 * Every item with `placeholder: true` is a licence-safe sample, NOT VGIS client work:
 * CC0 photos from rawpixel (source URL recorded), or imagery generated by VGIS
 * (scripts/generate-samples.py). Placeholders carry neutral "(sample)" titles, no client
 * names and no claims, and render with a visible "Sample" badge.
 *
 * To swap in real work: replace `image` (and `video`), set a real title, set `placeholder: false`.
 * One edit per item.
 *
 * Brand guardrails (owner, 13 Nov 2026):
 * - AI-assisted pieces: `aiAssisted: true`, category "ai" (AI video productions sit under Ads & Motion,
 *   owner via HP-Claude, 14 Nov 2026). Always labelled
 *   "AI-assisted, art-directed and finished by VGIS". Never in the hero or the signature 3D projects,
 *   and never presented as 3D renders or built projects.
 */

export type PortfolioCategory = "3d" | "xr" | "motion" | "ai" | "2d";

export const categories: { id: PortfolioCategory; label: string }[] = [
  { id: "3d", label: "3D" },
  { id: "xr", label: "XR" },
  { id: "motion", label: "Ads & Motion" },
  { id: "ai", label: "AI-assisted" },
  { id: "2d", label: "2D Branding" },
];

export const AI_LABEL = "AI-assisted, art-directed and finished by VGIS";

export type PortfolioItem = {
  id: string;
  title: string;
  category: PortfolioCategory;
  image: { src: string; width: number; height: number; alt: string };
  /** Video items: the image is the poster. Add a muted preview MP4, a playable MP4, and/or a YouTube/Vimeo ID. */
  video?: { previewMp4?: string; mp4?: string; youtubeId?: string; vimeoId?: string; vertical?: boolean };
  /** Link the tile to a project page. */
  href?: string;
  placeholder: boolean;
  aiAssisted?: boolean;
  /** Related service slug, for "see the service" links. */
  service?: string;
  /** Licence/origin record for placeholders and stock. */
  source?: string;
  /** Show in the home page grid. */
  featured?: boolean;
  /** Logo tiles: show the image whole (never cropped) on this brand colour. */
  ground?: string;
};

